select count(*) from user u left outer join user_product p on u.user_id = p.user_id left outer join product pd on p.product_id = pd.product_id where u.user_type = 'p'
and p.product_id is null
and p.product_id = #{type}
and u.status = #{status}
and u.user_name like concat('%',#{keyword},'%')

select count(*) from user where user_type = 'p' and status = 'WITHDRAWN'
and user_name like concat('%',#{keyword},'%')
and date(withdrawn_at) between #{startDate} and #{endDate}

select count(*) from user u join user_company c on u.user_id = c.user_id left outer join com_product p on u.user_id = p.user_id left outer join product pd on p.product_id = pd.product_id where u.user_type = 'c'
and p.product_id is null
and p.product_id = #{type}
and u.status = #{status}
and c.company_name like concat('%',#{keyword},'%')

select count(*) from user u join user_company c on u.user_id = c.user_id where u.user_type = 'c' and u.status = 'WITHDRAWN'
and c.company_name like concat('%',#{keyword},'%')
and date(u.withdrawn_at) between #{startDate} and #{endDate}

SELECT COUNT(*) FROM notice
AND (notice_title LIKE CONCAT ('%', #{keyword}, '%') OR status LIKE CONCAT ('%', #{keyword}, '%') OR user_type LIKE CONCAT ('%', #{keyword}, '%') )
AND notice_title LIKE CONCAT('%', #{keyword}, '%')
AND status = #{keyword}
AND user_type = #{keyword}

SELECT notice_id , notice_title , notice_content , reg_date , readcount , user_type , update_date , status FROM notice
AND (notice_title LIKE CONCAT ('%', #{keyword}, '%') OR status LIKE CONCAT ('%', #{keyword}, '%') OR user_type LIKE CONCAT ('%', #{keyword}, '%') )
AND notice_title LIKE CONCAT('%', #{keyword}, '%')
AND status = #{keyword}
AND user_type = #{keyword}
LIMIT ${offset}, ${limit}

mapper.insert:
INSERT INTO notice (
	notice_title
	, notice_content
	, reg_date
	, readcount
	, user_type
	, status
) VALUES (
	#{noticeTitle}
	, #{noticeContent}
	, NOW()
	,0
	, #{userType}
	, #{status}
)

mapper.update:
UPDATE notice
SET readcount = readcount + 1
WHERE notice_id = #{noticeId}

	UPDATE	notice
	SET 
		notice_title = #{noticeTitle}
		, notice_content = #{noticeContent}
		, user_type = #{userType}
		, status = #{status}
		, update_date = NOW()
	WHERE	
		notice_id= #{noticeId}

mapper.select:
SELECT job_id , comp_id , title , field , open_date , close_date , post_status FROM job_posting
post_check = 2
AND title LIKE CONCAT('%', #{keyword}, '%')
AND comp_id LIKE CONCAT('%', #{userId}, '%')
AND post_status = #{postStatus}
LIMIT #{offset}, #{limit}

SELECT *
FROM job_posting
WHERE job_id = #{jobId}

select count(*) from job_posting j join user_company c on j.comp_id = c.user_id where 1=1
and date(j.reg_date) between #{startDate} and #{endDate}
and c.company_name like concat('%',#{keyword},'%')
and j.post_check = #{submitStatus}

select j.job_id ,j.comp_id ,c.company_name ,j.title ,j.field ,j.task ,j.emp_type ,j.probation ,j.exp_type ,j.exp_year ,j.edu ,j.salary ,j.address ,j.is_remote ,j.mgr_name ,j.mgr_phone ,j.mgr_email ,j.is_public ,j.open_date ,j.close_date ,j.post_status ,j.reg_date ,j.post_check from job_posting j join user_company c on j.comp_id = c.user_id where 1=1
and date(j.reg_date) between #{startDate} and #{endDate}
and c.company_name like concat('%',#{keyword},'%')
and j.post_check = #{submitStatus}
order by
j.reg_date asc
j.reg_date desc
j.job_id desc
limit #{startRow}, #{listLimit}

select count(*) from pay p join product pd on p.product_id = pd.product_id join user u on p.user_id = u.user_id where 1=1
and date(p.pay_date) between #{startDate} and #{endDate}
and pd.product_name like concat('%',#{keyword},'%')
and u.user_type = #{userType}
and p.pay_status = #{payStatus}

select p.pay_id , p.user_id , u.user_name , u.phone , u.user_type , p.product_id , pd.product_name , p.pay_method , p.card_name , p.bank_name , p.deposit_account , p.deposit_name , p.pay_price , p.pay_date , p.issued_at , p.pay_status from pay p join product pd on p.product_id = pd.product_id join user u on p.user_id = u.user_id where 1=1
and date(p.pay_date) between #{startDate} and #{endDate}
and pd.product_name like concat('%',#{keyword},'%')
and u.user_type = #{userType}
and p.pay_status = #{payStatus}
order by
p.pay_date asc
p.pay_date desc
p.pay_id desc
limit #{startRow}, #{listLimit}

SELECT faq_id , faq_title , faq_content , category , user_type FROM faq
AND user_type=#{userType}
AND faq_title LIKE CONCAT('%', #{keyword}, '%')
AND faq_title LIKE CONCAT ('%', #{keyword}, '%')
AND faq_title LIKE CONCAT('%', #{keyword}, '%')
AND faq_title LIKE CONCAT('%', #{keyword}, '%')
AND category = #{category}
AND faq_id = #{faqId}
AND question LIKE CONCAT('%', #{keyword}, '%')
ORDER BY faq_id DESC
LIMIT #{offset}, #{limit}

mapper.insert:
INSERT INTO faq (
	faq_title
	, faq_content
	, category
	, user_type
) VALUES (
	#{faqTitle}
	, #{faqContent}
	,#{category}
	, #{userType}
)

mapper.update:
UPDATE
	faq
SET
	faq_title = #{faqTitle}
	, faq_content = #{faqContent}
	, category = #{category}
	, user_type = #{userType}
WHERE	
	faq_id = #{faqId}

UPDATE 
	banner
SET
	is_display = #{isDisplay}
WHERE
	ad_id = #{adId}

