SELECT count(*) FROM board_post
AND title LIKE CONCAT('%', #{keyword}, '%')
AND status = #{status}
AND created_at >= #{startDate}
AND created_at <= CONCAT(#{endDate}, ' 23:59:59')
AND author_member_id LIKE CONCAT('%', #{userId}, '%')

SELECT post_id , title , author_member_id , created_at , status FROM board_post
AND created_at >= #{startDate}
AND created_at <= CONCAT(#{endDate}, ' 23:59:59')
AND author_member_id = #{userId}
AND status = #{status}
AND title LIKE CONCAT('%', #{keyword}, '%')
ORDER BY created_at DESC LIMIT #{offset}, #{limit}
